int lsf_factory_device_firmware_retire(const void *address)
{
    struct lsf_factory_device_firmware *owned;
    struct lsf_prepaid_ticket pci;
    unsigned long flags;
    int result;
    spin_lock_irqsave(&pool_lock, flags);
    result = lsf_factory_device_firmware_pci(address, &pci);
    if (!result)
        goto out;
    if (result < 0)
        goto poison;
    result = 0;
    if (!factory.device->firmware.slot)
        goto out;
    owned = lsf_factory_device_firmware_for_pci(address, pci);
    if (!owned)
        goto poison;
    if (owned->returned)
        goto out;
    if (owned->retirement)
        goto poison;
    owned->retirement = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    lsf_factory_device_firmware_schedule();
    return 1;
poison:
    lsf_factory_device_firmware_poison();
    result = -1;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

void lsf_factory_device_core_tail_finish.text:
void lsf_factory_device_core_tail_finish(const void *kobject)
{
    struct lsf_factory_device_firmware *owned;
    struct lsf_prepaid_ticket pci;
    const void *address;
    unsigned long flags;
    spin_lock_irqsave(&pool_lock, flags);
    /* Revoke the EXACT current callback borrow before every later
     * validation/error/queue path. The original bank retains this
     * state even if a poisoned record can no longer be looked up.
     * A foreign task never clears the real callback task borrow. */
    if (!factory.device || factory.device->core_tail_task != current)
        goto poison;
    factory.device->core_tail_task = NULL;
    if (lsf_factory_device_core_parent(kobject,
            offsetof(struct pci_dev, dev) + offsetof(struct device, kobj), &pci, &address) != 1 ||
        !(owned = lsf_factory_device_firmware_for_pci(address, pci)) ||
        !owned->core_initialized || !owned->core_tail_active || !owned->retirement ||
        owned->queued || owned->returned || owned->core_tail_complete)
        goto poison;
    if (!lsf_factory_device_core_child_retired(owned))
        goto poison;
    /* No kobject/device dereference: original type release may have logically
     * freed them. Exact parent birth and the prepaid descriptor retain storage.
     * All original core/name/parent cleanup has now returned without our locks. */
    owned->core_tail_active = 0;
    owned->core_tail_complete = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    lsf_factory_device_firmware_schedule();
    return;
poison:
    lsf_factory_device_firmware_poison();
    spin_unlock_irqrestore(&pool_lock, flags);
}

