    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_factory_device_recipient_current_locked(source, NULL) ||
        !lsf_device_queue(&factory.pool, factory.device->key, ticket, LSF_DEVICE_RECIPIENT_WORK) ||
